package com.nigson.commerce.pricing;
import java.util.*;
import java.time.Clock;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.*;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
public final class PriceBookService {
 private final PriceBookRepository repository;private final PricingAuthority authority;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final JdbcTemplate jdbc;private final TransactionTemplate reads;private final io.micrometer.core.instrument.MeterRegistry metrics;
 public PriceBookService(PriceBookRepository repository,PricingAuthority authority,PlatformStore commands,AuditWriter audit,Clock clock,JdbcTemplate jdbc,org.springframework.transaction.PlatformTransactionManager manager,io.micrometer.core.instrument.MeterRegistry metrics){this.repository=repository;this.authority=authority;this.commands=commands;this.audit=audit;this.clock=clock;this.jdbc=jdbc;this.metrics=metrics;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);reads.setTimeout(3);}
 public PricingValues.Page list(ActorAssertion.Actor actor,PricingValues.Query q){authority.require(actor,"SALES");return reads.execute(s->{jdbc.execute("SET LOCAL statement_timeout='2s'");authority.require(actor,"SALES");return repository.list(q);});}
 private PricingValues.Book command(ActorAssertion.Actor actor,String role,String api,String key,Object body,UUID correlation,java.util.function.Supplier<PricingValues.Book> change,AuditValues.Action action){authority.require(actor,role);ApiValues.idempotencyKey(key);if(correlation==null||correlation.equals(new UUID(0,0)))throw ApiValues.invalid();try{var response=commands.executeLocal(actor.party().toString(),api,key,EventCodec.JSON.valueToTree(body),db->{jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");authority.stabilize(actor,role);var after=change.get();audit.append(actor.party().toString(),AuditValues.ActorKind.USER,action,AuditValues.Resource.PRICE_BOOK,after.id(),correlation,AuditValues.Reason.CONFIGURATION_CHANGE,null,Map.of("version",after.version(),"revision",after.revision(),"currency",after.currency(),"enabled",after.active()),null);if(action==AuditValues.Action.PRICE_ACTIVATION)event(after,actor.party().toString(),correlation);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCommit(){metrics.counter("nigson.pricing.commands","operation",switch(api){case "API-027"->"CREATE";case "API-028"->"ACTIVATE";default->"REVISE";}).increment();}});return new PlatformStore.Response(201,EventCodec.JSON.valueToTree(after),after.id());});return EventCodec.JSON.treeToValue(response.body(),PricingValues.Book.class);}catch(org.springframework.dao.DataAccessException failure){for(Throwable cause=failure;cause!=null;cause=cause.getCause())if(cause instanceof java.sql.SQLException sql&&Set.of("55P03","57014").contains(sql.getSQLState()))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_IN_PROGRESS);throw failure;}}
 public PricingValues.Book create(ActorAssertion.Actor actor,PricingValues.Input value,String key,UUID correlation){return command(actor,"SALES","API-027",key,value,correlation,()->repository.create(value,actor.party().toString()),AuditValues.Action.PRICE_CREATE);}
 public PricingValues.Book revise(ActorAssertion.Actor actor,UUID id,long expected,PricingValues.Input value,String key,UUID correlation){version(expected);return command(actor,"SALES","API-151",key,Map.of("id",id,"version",expected,"body",value),correlation,()->repository.revise(id,expected,value,actor.party().toString()),AuditValues.Action.PRICE_REVISION);}
 public PricingValues.Book activate(ActorAssertion.Actor actor,UUID id,long expected,String reason,String key,UUID correlation){version(expected);if(reason==null||reason.strip().length()<10||reason.length()>300||reason.codePoints().anyMatch(c->Character.isISOControl(c)||Character.getType(c)==Character.FORMAT))throw ApiValues.invalid();return command(actor,"FINANCE","API-028",key,Map.of("id",id,"version",expected,"reason",reason),correlation,()->repository.activate(id,expected,actor.party().toString()),AuditValues.Action.PRICE_ACTIVATION);}
 private static void version(long expected){if(expected<0||expected==Long.MAX_VALUE)throw ApiValues.invalid();}
 private void event(PricingValues.Book b,String actor,UUID correlation){var envelope=new LinkedHashMap<String,Object>();envelope.put("event_id",EventCodec.uuid7(clock.instant()));envelope.put("event_type","pricing.changed.v1");envelope.put("schema_version",1);envelope.put("producer","commerce");envelope.put("occurred_at",clock.instant());envelope.put("aggregate_id",b.id());envelope.put("aggregate_version",b.version());envelope.put("organization_id",null);envelope.put("correlation_id",correlation);var span=io.opentelemetry.api.trace.Span.current().getSpanContext();envelope.put("traceparent",span.isValid()?"00-"+span.getTraceId()+"-"+span.getSpanId()+"-"+span.getTraceFlags().asHex():null);var payload=new LinkedHashMap<String,Object>();payload.put("entity_type","PRICE_BOOK");payload.put("entity_id",b.id());payload.put("revision",b.revision());payload.put("market_id",null);envelope.put("payload",payload);commands.append(EventCodec.JSON.writeValueAsString(envelope),actor);}
}
